function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 50)) return 'Each value of nums is an integer from 0 to 50.';
  if (!Number.isInteger(k) || k < 0 || k >= 64) return 'k is an integer from 0 to 63.';
  return null;
}

