function minimumSubarrayLength(nums, k) {
  const n = nums.length;
  let best = Infinity;

  for (let left = 0; left < n; left++) {
    let orValue = 0;
    for (let right = left; right < n; right++) {
      orValue |= nums[right];
      if (orValue >= k) {
        best = Math.min(best, right - left + 1);
        break;
      }
    }
  }
  return best === Infinity ? -1 : best;
}

