function minimumSubarrayLength(nums, k) {
  // Try lengths from shortest to longest and OR each window from scratch.
  for (let len = 1; len <= nums.length; len++) {
    for (let start = 0; start + len <= nums.length; start++) {
      const value = nums.slice(start, start + len).reduce((acc, x) => acc | x, 0);
      if (value >= k) return len;
    }
  }
  return -1;
}

