function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 8);
  const bitsOnly = rand() < 0.5;
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (bitsOnly) nums.push(rand() < 0.3 ? 0 : 1 << Math.floor(rand() * 6));
    else nums.push(Math.floor(rand() * 51));
  }
  const k = Math.floor(rand() * 64);
  return [nums, k];
}
